import { LEGAL_CONFIG } from "@/lib/legalConfig";
import { Mail, MapPin, Phone, Terminal } from "lucide-react";

export default function ContactPage() {
  return (
    <main className="max-w-2xl mx-auto min-h-screen bg-background text-white p-6 font-mono crt-overlay">
      <div className="space-y-6 pt-6">
        <div className="inline-flex items-center gap-2 px-3 py-1 bg-surface border border-neonViolet/50 text-neonViolet text-[10px] uppercase tracking-widest">
          <Terminal className="w-3.5 h-3.5" /> OFFICIAL SUPPORT
        </div>
        <h1 className="text-3xl font-black uppercase text-neonMint">CONTACT US</h1>

        <div className="cyber-panel p-6 space-y-4 border-surfaceBorder bg-black/60">
          <div className="flex items-start gap-3">
            <Mail className="w-5 h-5 text-neonMint mt-0.5" />
            <div>
              <div className="text-xs text-gray-400 uppercase">Support Email</div>
              <div className="text-sm text-white font-bold">{LEGAL_CONFIG.contactEmail}</div>
            </div>
          </div>

          <div className="flex items-start gap-3">
            <Phone className="w-5 h-5 text-neonMint mt-0.5" />
            <div>
              <div className="text-xs text-gray-400 uppercase">Phone Support</div>
              <div className="text-sm text-white font-bold">{LEGAL_CONFIG.contactPhone}</div>
            </div>
          </div>

          <div className="flex items-start gap-3">
            <MapPin className="w-5 h-5 text-neonMint mt-0.5" />
            <div>
              <div className="text-xs text-gray-400 uppercase">Operating Address</div>
              <div className="text-sm text-white font-bold">{LEGAL_CONFIG.registeredAddress}</div>
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}